import { DOC_CONCERNS, DOC_FORMS, computeLocation } from "@govlab/docs";

const registries = { concerns: DOC_CONCERNS, forms: DOC_FORMS, owners: ["project"] };
const result = computeLocation({ concern: "scaling", form: "guide", member: "project", name: "scale-web", registries });
console.log(result.ok ? result.path : result.detail);

import { conventionHits, pathReferences, validateSpine } from "@govlab/docs";

const source = "---
type: guide
name: scale-web
summary: How to scale.
---

# Scale web
";
const spine = validateSpine(source, ["type", "name", "summary"], { requireFrontmatter: true, requireTitle: true });
console.log(spine.length, conventionHits(source).length, pathReferences(source).length);
